  private static SQLiteDatabase database(){SQLiteDatabase db=SQLiteDatabase.create(null);db.execSQL("CREATE TABLE messages(id TEXT PRIMARY KEY,created INTEGER NOT NULL,data TEXT NOT NULL)");db.execSQL("CREATE TABLE memories(id TEXT PRIMARY KEY,created INTEGER NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL)");db.execSQL("CREATE TABLE files(id TEXT PRIMARY KEY,created INTEGER NOT NULL,data TEXT NOT NULL)");MemorySchema.install(db);return db;}
