      JSONObject q=question("我明天有什么安排","2026-10-12T23:30:00+08:00","Asia/Shanghai");put(db,row("meeting","项目例会","2026-10-13T09:00:00+08:00","2026-10-13T10:00:00+08:00"));put(db,row("old-tomorrow","明天去看展","2026-10-12T15:00:00+08:00","2026-10-12T16:00:00+08:00"));put(db,row("keyword-note","明天安排些什么的普通资料","2026-10-13T15:00:00+08:00","2026-10-13T16:00:00+08:00").put("kind","note").put("type","note"));int before=count(db);JSONObject answer=ScheduleQuery.answer(db,q);ok(has(answer,"meeting")&&!has(answer,"old-tomorrow")&&!has(answer,"keyword-note"),"Query date, not record keyword tomorrow, determines schedule membership");ok(answer.getString("reply").contains("2026年10月13日")&&answer.getString("reply").contains("09:00"),"Reply includes a concrete date and verified clock");ok(answer.getJSONObject("queryTime").getString("date").equals("2026-10-13")&&answer.getJSONObject("queryTime").getString("endDate").equals("2026-10-13"),"A single-day range has an inclusive display endDate");ok(count(db)==before&&answer.getJSONArray("memories").length()==0&&answer.optString("intent").equals("query"),"Answering a question writes no arrangement");
      JSONObject delayed=new JSONObject(q.toString()).put("created",at("2030-01-01T12:00:00+08:00"));ok(has(ScheduleQuery.answer(db,delayed),"meeting"),"Retry time does not move the original query date");ok(has(ScheduleQuery.answer(db,question("我今天有什么安排","2026-10-12T08:00:00+08:00","Asia/Shanghai")),"old-tomorrow"),"An old tomorrow record is correctly retrieved as today");
      for(String status:new String[]{"completed","archived","cancelled"})put(db,row("status-"+status,"排除状态","2026-10-13T10:00:00+08:00","2026-10-13T11:00:00+08:00").put("status",status));for(String truth:new String[]{"historical","retracted","disputed"})put(db,row("truth-"+truth,"排除旧说法","2026-10-13T11:00:00+08:00","2026-10-13T12:00:00+08:00").put("truthState",truth));put(db,row("cancelled-flag","已取消的会","2026-10-13T12:00:00+08:00","2026-10-13T13:00:00+08:00").put("cancelledAt",at("2026-10-12T12:00:00+08:00")));put(db,row("cancelled-state","已取消的事","2026-10-13T12:00:00+08:00","2026-10-13T13:00:00+08:00").put("eventState","cancelled"));put(db,row("occurred","已经发生","2026-10-13T12:00:00+08:00","2026-10-13T13:00:00+08:00").put("kind","event").put("eventState","occurred"));put(db,row("review","文字改过旧时间不可信","2026-10-13T12:00:00+08:00","2026-10-13T13:00:00+08:00").put("structuredReview",true));put(db,row("replaced","已被新安排替代","2026-10-13T12:00:00+08:00","2026-10-13T13:00:00+08:00").put("supersededBy","new-plan"));answer=ScheduleQuery.answer(db,q);ok(answer.getJSONObject("queryTime").getInt("count")==1,"Completed, cancelled, occurred, historical and stale structures are excluded");
      JSONObject move=row("move","线上碰头","2026-10-13T14:00:00+08:00","2026-10-13T15:00:00+08:00");put(db,move);ok(has(ScheduleQuery.answer(db,q),"move"),"Plan initially belongs to tomorrow");move.put("time",new JSONObject(move.getJSONObject("time").toString()).put("start",at("2026-10-14T14:00:00+08:00")).put("end",at("2026-10-14T15:00:00+08:00"))).put("dueAt","2026-10-14T14:00:00+08:00");put(db,move);ok(!has(ScheduleQuery.answer(db,q),"move")&&has(ScheduleQuery.answer(db,question("后天有哪些安排","2026-10-12T23:30:00+08:00","Asia/Shanghai")),"move"),"A rescheduled record updates the indexed date and disappears from the old day");
      JSONObject uncertain=row("known-date","明天8点开会","2026-10-13T08:00:00+08:00","2026-10-13T08:01:00+08:00").put("time",TimeAnchor.resolve("明天8点",q,false,null,"future"));put(db,uncertain);answer=ScheduleQuery.answer(db,q);ok(has(answer,"known-date")&&answer.getString("reply").contains("时刻未定"),"A known tomorrow date remains visible even when the clock's AM/PM is unknown");try(Cursor c=db.rawQuery("SELECT event_start,remind_at,data FROM memories WHERE id='known-date'",null)){c.moveToFirst();ok(c.getLong(0)==0&&c.getLong(1)==0&&new JSONObject(c.getString(2)).getJSONObject("time").optString("state").equals("ambiguous_clock"),"An overview does not invent an exact event time, change source semantics or schedule a reminder");}
      JSONObject onlyAlarm=row("alarm-only","只有提醒时刻","2026-10-13T18:00:00+08:00","2026-10-13T18:01:00+08:00");onlyAlarm.remove("time");onlyAlarm.put("remindAt",at("2026-10-13T18:00:00+08:00"));put(db,onlyAlarm);put(db,row("different-alarm","真实行程在后天","2026-10-14T18:00:00+08:00","2026-10-14T19:00:00+08:00").put("remindAt",at("2026-10-13T18:00:00+08:00")));put(db,row("expired-alarm","行程还有效但提醒已过期","2026-10-13T19:00:00+08:00","2026-10-13T20:00:00+08:00").put("remindAt",at("2026-10-11T18:00:00+08:00")));answer=ScheduleQuery.answer(db,q);ok(!has(answer,"alarm-only")&&!has(answer,"different-alarm")&&has(answer,"expired-alarm"),"Reminder timestamps are not mistaken for event dates or completion");
