      JSONObject spring=ScheduleQuery.range(question("明天有什么安排","2026-03-07T12:00:00-05:00","America/New_York")),autumn=ScheduleQuery.range(question("明天有什么安排","2026-10-31T12:00:00-04:00","America/New_York"));ok(spring.getLong("end")-spring.getLong("start")==23L*3600000L&&autumn.getLong("end")-autumn.getLong("start")==25L*3600000L,"Local calendar days respect DST rather than fixed 24-hour arithmetic");
      JSONObject week=ScheduleQuery.range(question("这周有什么安排","2026-10-12T12:00:00+08:00","Asia/Shanghai")),next=ScheduleQuery.range(question("下周有什么安排","2026-10-12T12:00:00+08:00","Asia/Shanghai"));ok(week.getString("startDate").equals("2026-10-12")&&week.getString("endDate").equals("2026-10-18")&&next.getString("startDate").equals("2026-10-19")&&next.getString("endDate").equals("2026-10-25"),"Calendar weeks have explicit Monday-to-Sunday coverage");ok(ScheduleQuery.range(question("周二有什么安排","2026-10-12T12:00:00+08:00","Asia/Shanghai")).getString("date").equals("2026-10-13"),"A bare weekday resolves from the query's own calendar");
